"""Unique Paths III — backtracking that must cover every walkable square.

The path is only counted when it lands on the target *and* has visited all
empty cells, tracked with a simple remaining counter.

Time: O(4^(m*n))   Space: O(m*n)
"""
from typing import List


class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        start = (0, 0)
        empty = 1                      # the starting square counts
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    start = (i, j)
                elif grid[i][j] == 0:
                    empty += 1

        def walk(i: int, j: int, remaining: int) -> int:
            if not (0 <= i < m and 0 <= j < n) or grid[i][j] == -1:
                return 0
            if grid[i][j] == 2:
                return 1 if remaining == 0 else 0
            saved = grid[i][j]
            grid[i][j] = -1
            total = sum(walk(i + di, j + dj, remaining - 1)
                        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)))
            grid[i][j] = saved
            return total

        return walk(start[0], start[1], empty)
